import { T, Var, Num, Currency, DateTime, RelativeTime, Branch, Plural, Derive } from 'gt-next';
import { Branch as Subject } from 'gt-next';
import { Card, renderLabel } from './widgets';

export function Page(props) {
  const {
  name, count, mode, show, items, label, value, custom,
  settings, context, locales, amount, date
} = props;
  return (<main><h1>Account {name}</h1><Subject branch={mode} data-selector={value} data-label={<span>Data {name}</span>} aria-label={label} ref={custom}>Fallback {name}</Subject><footer>Next</footer></main>);
}

